<?php defined('BASEPATH') OR exit('No direct script access allowed');class Contact extends MY_Controller{function __construct(){parent::__construct();$this->load->model('Contact_model','contact');}function form(){$d=$this->body();foreach(array('name','email','category','subject','message') as $f)if(trim($d[$f]??'')==='')return $this->fail('VALIDATION_ERROR',$f.' is required',422);if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL)||strlen($d['message'])>10000)return $this->fail('VALIDATION_ERROR','Invalid contact request',422);return $this->respond($this->contact->submit($d,$this->optional_auth()),201);}function my_requests($id=NULL){$c=$this->require_auth();if(!$c)return;$r=$this->contact->mine($c['sub'],$id);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Contact request not found',404);}function my_messages($id){$c=$this->require_auth();if(!$c)return;$r=$this->contact->messages($id,$c['sub']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Contact request not found',404);}function assistant_start(){$d=$this->body();$message=trim($d['message']??'');if($message==='')return $this->fail('VALIDATION_ERROR','Message required',422);list($id,$msgs)=$this->contact->ai_start($message,$d['name']??NULL,$d['email']??NULL,NULL);return $this->ai_reply($id,$msgs);}function assistant_message(){$d=$this->body();$row=$this->contact->ai_get($d['conversationId']??'');if(!$row)return $this->fail('NOT_FOUND','Assistant conversation not found',404);$msgs=json_decode($row['messages'],TRUE)?:array();$msgs[]=array('role'=>'user','content'=>trim($d['message']??''));return $this->ai_reply($row['id'],$msgs);}private function ai_reply($id,$msgs){$this->load->library('Ai_provider');array_unshift($msgs,array('role'=>'system','content'=>'You are a concise customer support assistant. Provide helpful guidance and recommend submitting a support request when human help is required.'));$out=$this->ai_provider->complete($msgs);array_shift($msgs);if(!$out['ok'])return $this->fail($out['code'],$out['message'],503);$msgs[]=array('role'=>'assistant','content'=>$out['content']);$this->contact->ai_save($id,$msgs);return $this->respond(array('conversationId'=>$id,'message'=>$out['content'],'escalate'=>FALSE));}private function admin_auth(){ $c=$this->require_auth();if(!$c)return NULL;$this->load->model('Admin_model','admin');if(!$this->admin->access($c['sub'],$c['organizationId']??NULL)){$this->fail('FORBIDDEN','Administrator access required',403);return NULL;}return $c;}function admin_dashboard(){if(!$this->admin_auth())return;return $this->respond($this->contact->dashboard());}function admin_requests(){if(!$this->admin_auth())return;$p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:20)));return $this->respond($this->contact->admin_list(array('status'=>$this->input->get('status'),'category'=>$this->input->get('category'),'priority'=>$this->input->get('priority'),'department'=>$this->input->get('department')),$p,$pp));}function admin_request($id){if(!$this->admin_auth())return;$r=$this->contact->admin_get($id);return $r?$this->respond(array('request'=>$r,'messages'=>$this->contact->admin_messages($id),'history'=>$this->contact->history($id))):$this->fail('NOT_FOUND','Contact request not found',404);}function admin_respond($id){$c=$this->admin_auth();if(!$c)return;$d=$this->body();if(trim($d['body']??'')==='')return $this->fail('VALIDATION_ERROR','Response body required',422);$r=$this->contact->respond($id,$c['sub'],$d);return $r?$this->respond($r,201):$this->fail('NOT_FOUND','Contact request not found',404);}function admin_assign($id){$c=$this->admin_auth();if(!$c)return;$r=$this->contact->assign($id,$c['sub'],$this->body());return $r?$this->respond($r):$this->fail('NOT_FOUND','Contact request not found',404);}function admin_transition($id){$c=$this->admin_auth();if(!$c)return;$to=$this->body()['to']??'';if(!in_array($to,array('new','ai_handling','awaiting_human','assigned','in_progress','awaiting_customer','resolved','closed'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid status',422);$r=$this->contact->transition($id,$c['sub'],$to);return $r?$this->respond($r):$this->fail('NOT_FOUND','Contact request not found',404);}}
